import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';

// Pages
import Login from './pages/Login';
import Signup from './pages/Signup';

// A simple placeholder for the dashboard until we build it
const DashboardPlaceholder = () => (
    <div style={{ padding: '2rem', textAlign: 'center' }}>
        <h1>Welcome to the WebVox Dashboard</h1>
        <p>We'll build the Hasura GraphQL iframe here next!</p>
    </div>
);

function App() {
    return (
        <AuthProvider>
            <Router>
                <Routes>
                    <Route path="/" element={<Navigate to="/login" />} />
                    <Route path="/login" element={<Login />} />
                    <Route path="/signup" element={<Signup />} />

                    {/* We'll protect this route later */}
                    <Route path="/dashboard/graphql" element={<DashboardPlaceholder />} />
                </Routes>
            </Router>
        </AuthProvider>
    );
}

export default App;
